{"content":"import json

def pos(f, r):
    # f 0..7 (a..h), r 0..7 (rank1..rank8); board string rank8 first, 9 chars per rank incl '/'
    return (7 - r) * 9 + f

def sqname(f, r):
    return chr(ord('a') + f) + str(r + 1)

A8 = pos(0, 7)
H8 = pos(7, 7)
A1 = pos(0, 0)
H1 = pos(7, 0)
E1 = pos(4, 0)

def is_sep(i):
    return i % 9 == 8

def mid_pattern(p1, p2, path=()):
    pathset = set(path)
    out = []
    for i in range(p1 + 1, p2):
        if i in pathset:
            out.append('1')
        elif is_sep(i):
            out.append('/')
        else:
            out.append('.')
    return ''.join(out)

def marker_for(src_piece, srcpos, dstpos):
    if src_piece == 'K':
        base = 'K'
    elif src_piece == 'R' and srcpos == A1:
        base = 'A'
    elif src_piece == 'R' and srcpos == H1:
        base = 'H'
    else:
        base = 'N'
    if dstpos == A8:
        return base + 'a8'
    if dstpos == H8:
        return base + 'h8'
    return base

rules = []

# P0: sentinel first space -> |
rules.append(["^([^ ]+) ", "\\1|"])

# digit expansion, board only (before |)
for d, rep in [('8','11111111'),('7','1111111'),('6','111111'),('5','11111'),('4','1111'),('3','111'),('2','11')]:
    rules.append([d + "(?=[^|]*\\|)", rep])

def add_move(srcpos, dstpos, src_piece, dst_class, new_src, new_dst, new_ep, mark, extra_board_cond=None, ep_cond=None):
    # extra_board_cond: not needed (dst_class covers); ep_cond: required ep square name or None
    p1 = min(srcpos, dstpos)
