# Generic single-piece move rule builder with optional path set
def move_rule(srcpos, dstpos, src_char, dst_pat, new_src_char, new_dst_char, new_ep, mark, path=()):
    p1 = min(srcpos, dstpos)
    p2 = max(srcpos, dstpos)
    mid = mid_pattern(p1, p2, path)
    pre_len = p1
    suf_len = 71 - p2 - 1
    if srcpos < dstpos:
        c1, c2 = src_char, dst_pat
        n1, n2 = new_src_char, new_dst_char
    else:
        c1, c2 = dst_pat, src_char
        n1, n2 = new_dst_char, new_src_char
    pat = ("^(?P<pre>.{%d})" % pre_len) + c1 + ("(?P<mid>%s)" % mid) + c2 + ("(?P<suf>.{%d})" % suf_len) + "\\|w (?P<cast>\\S+) \\S+ \\d+ \\d+(?=\\n|$)"
    rep = "\\g<0>\\n\\g<pre>" + n1 + "\\g<mid>" + n2 + "\\g<suf>|b \\g<cast> " + new_ep + " 0 " + mark
    rules.append([pat, rep])

def dst_mark(src_piece, srcpos, dstpos):
    return marker_for(src_piece, srcpos, dstpos)

