def ray_moves(f, r, df, dr):
    out = []
    path = []
    nf, nr = f+df, r+dr
    while 0 <= nf < 8 and 0 <= nr < 8:
        d = pos(nf, nr)
        out.append((d, list(path)))
        path.append(d)
        nf += df; nr += dr
    return out

