def attacker_lookaheads(tx, ty):
    # square (tx,ty) must not be attacked by black in original
    X = pos(tx, ty)
    lhs = []
    # knights
    for df, dr in ((1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)):
        yf, yr = tx+df, ty+dr
        if 0 <= yf < 8 and 0 <= yr < 8:
            Y = pos(yf, yr)
            lhs.append("(?!.{%d}n)" % Y)
    # pawns: black pawn attacks downward; attacker one rank above target
    for df in (-1, 1):
        yf, yr = tx+df, ty+1
        if 0 <= yf < 8 and 0 <= yr < 8:
            Y = pos(yf, yr)
            lhs.append("(?!.{%d}p)" % Y)
    # king
    for df in (-1,0,1):
        for dr in (-1,0,1):
            if df==0 and dr==0: continue
            yf, yr = tx+df, ty+dr
            if 0 <= yf < 8 and 0 <= yr < 8:
                Y = pos(yf, yr)
                lhs.append("(?!.{%d}k)" % Y)
    # sliders: rays from X
    for df, dr, cls in ((1,0,'[rq]'),(-1,0,'[rq]'),(0,1,'[rq]'),(0,-1,'[rq]'),(1,1,'[bq]'),(1,-1,'[bq]'),(-1,1,'[bq]'),(-1,-1,'[bq]')):
        ray = []
        yf, yr = tx+df, ty+dr
        while 0 <= yf < 8 and 0 <= yr < 8:
            Y = pos(yf, yr)
            ray.append(Y)
            yf += df; yr += dr
        for j, Y in enumerate(ray):
            between = ray[:j]
            p1 = min(X, Y); p2 = max(X, Y)
            mid = mid_pattern(p1, p2, between)
            if X < Y:
                inner = ".{%d}" % p1 + "." + mid + cls
                # need full: .{p1} + '.'(X) + mid + cls(Y)? X char is '.' (any)
                # construct: .{p1} then X-char '.' then mid then attacker
                la = "(?!.{%d}.%s%s)" % (p1, mid, cls)
            else:
                la = "(?!.{%d}%s%s.)" % (p1, cls, mid)
            lhs.append(la)
    return lhs

